// ── Auth helpers (Supabase GoTrue REST API, no SDK needed) ──
const AUTH_STORAGE_KEY = "tps_auth_session";

const authSignIn = async (email, password) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/token?grant_type=password", {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Login failed");
  return data; // { access_token, refresh_token, user, expires_at, ... }
};

const authRequestPasswordReset = async (email) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/recover", {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email }),
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.error_description || data.msg || "Could not send reset email.");
  }
  return true;
};

const authRefresh = async (refreshToken) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/token?grant_type=refresh_token", {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ refresh_token: refreshToken }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Session refresh failed");
  return data;
};

const authUpdatePassword = async (accessToken, newPassword) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/user", {
    method: "PUT",
    headers: {
      "apikey": SUPABASE_KEY,
      "Authorization": "Bearer " + accessToken,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ password: newPassword }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Password update failed");
  return data;
};

const saveSession = (session) => {
  try { localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(session)); } catch(e) {}
};
const loadSession = () => {
  try { const s = localStorage.getItem(AUTH_STORAGE_KEY); return s ? JSON.parse(s) : null; } catch(e) { return null; }
};
const clearSession = () => {
  try { localStorage.removeItem(AUTH_STORAGE_KEY); } catch(e) {}
};

// ─── Login View ───────────────────────────────────────────────────────────────
// ─── Set Password View (shown when arriving from an invite/recovery email link) ──
function SetPasswordView({ inviteToken, onSuccess }) {
  const [password,        setPassword]        = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error,           setError]           = useState("");
  const [saving,          setSaving]          = useState(false);

  const handleSetPassword = async (e) => {
    e.preventDefault();
    setError("");
    if (password.length < 6) { setError("Password must be at least 6 characters."); return; }
    if (password !== confirmPassword) { setError("Passwords do not match."); return; }
    setSaving(true);
    try {
      // Grab the user's email BEFORE changing the password, while the invite
      // token's session is still alive.
      const userRes = await fetch(SUPABASE_URL + "/auth/v1/user", {
        headers: { "apikey": SUPABASE_KEY, "Authorization": "Bearer " + inviteToken },
      });
      const userData = await userRes.json();
      if (!userRes.ok || !userData?.email) throw new Error("Could not finish setting up your account. Please ask your admin to resend the invite.");

      // Setting the password invalidates the invite token's session (this is
      // intentional Supabase behavior) — so we must NOT reuse inviteToken
      // after this point for anything.
      await authUpdatePassword(inviteToken, password);

      // Sign in fresh with the new password to get a brand new, valid session.
      const freshSession = await authSignIn(userData.email, password);
      onSuccess(freshSession);
    } catch(err) {
      setError(err.message || "Something went wrong setting your password.");
    }
    setSaving(false);
  };

  return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{maxWidth:340, width:"100%", padding:"0 24px"}}>
        <img src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64} alt="BlacktopIQ"
          style={{width:"100%", maxWidth:240, display:"block", margin:"0 auto 28px"}}/>
        <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Welcome!</h1>
        <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
          Set a password to finish creating your account.
        </p>
        <form onSubmit={handleSetPassword}>
          <label style={S.formLabel}>New Password
            <input type="password" value={password} onChange={e => setPassword(e.target.value)}
              style={S.input} placeholder="At least 6 characters" required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Confirm Password
            <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)}
              style={S.input} placeholder="Re-enter password" required/>
          </label>
          {error && <div style={{color:C.danger, fontSize:13, marginTop:10}}>{error}</div>}
          <button type="submit" style={{...S.btnPrimary, width:"100%", marginTop:18, opacity:saving?0.6:1}} disabled={saving}>
            {saving ? "Setting up..." : "🔑 Set Password & Continue"}
          </button>
        </form>
      </div>
    </div>
  );
}

// ─── Join Company View (redeeming a brand-new-company invite link) ────────────
// Different from SetPasswordView above: that one is for someone Supabase
// already knows about (invited by email into an existing company). This is
// for someone who doesn't have an account yet at all, arriving via a custom
// tenant_invites token, about to create their OWN company from scratch.
function JoinCompanyView({ token, onSuccess }) {
  const [companyName, setCompanyName] = useState("");
  const [phone,        setPhone]        = useState("");
  const [email,        setEmail]        = useState("");
  const [password,     setPassword]     = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error,        setError]        = useState("");
  const [saving,       setSaving]       = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (!companyName.trim()) { setError("Company name is required."); return; }
    if (!email.trim()) { setError("Email is required."); return; }
    if (password.length < 8) { setError("Password must be at least 8 characters."); return; }
    if (password !== confirmPassword) { setError("Passwords do not match."); return; }
    setSaving(true);
    try {
      const res = await fetch("/api/redeem-tenant-invite", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token, email: email.trim(), password, companyName: companyName.trim(), phone: phone.trim() }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Could not set up your company.");

      // Account + company now exist server-side — sign in for real to get a
      // proper session, same as any normal login.
      const freshSession = await authSignIn(email.trim(), password);
      onSuccess(freshSession);
    } catch(err) {
      setError(err.message || "Something went wrong setting up your company.");
    }
    setSaving(false);
  };

  return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{maxWidth:380, width:"100%", padding:"0 24px"}}>
        <img src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64} alt="BlacktopIQ"
          style={{width:"100%", maxWidth:240, display:"block", margin:"0 auto 28px"}}/>
        <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Welcome to BlacktopIQ</h1>
        <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
          Set up your company and create your admin account.
        </p>
        <form onSubmit={handleSubmit}>
          <label style={S.formLabel}>Company Name
            <input value={companyName} onChange={e => setCompanyName(e.target.value)} style={S.input} placeholder="e.g. Smith Paving Co." required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Phone (optional)
            <input type="tel" value={phone} onChange={e => setPhone(e.target.value)} style={S.input}/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Your Email
            <input type="email" value={email} onChange={e => setEmail(e.target.value)} style={S.input} required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Password
            <input type="password" value={password} onChange={e => setPassword(e.target.value)} style={S.input} placeholder="At least 8 characters" required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Confirm Password
            <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} style={S.input} required/>
          </label>
          {error && <div style={{color:C.danger, fontSize:13, marginTop:10}}>{error}</div>}
          <button type="submit" style={{...S.btnPrimary, width:"100%", marginTop:18, opacity:saving?0.6:1}} disabled={saving}>
            {saving ? "Setting up your company..." : "🚀 Create My Company"}
          </button>
        </form>
      </div>
    </div>
  );
}

// ─── Profile Setup Wizard (first login, non-admin roles) ──────────────────────
// Estimator/Crew/Crew Lead/Manager accounts must complete this before they
// can use the app. Admins get a separate, more involved company setup flow
// (built later) and never see this screen.
function ProfileSetupWizard({ accessToken, userId, onComplete }) {
  const [firstName, setFirstName] = useState("");
  const [lastName,  setLastName]  = useState("");
  const [phone,     setPhone]     = useState("");
  const [dob,       setDob]       = useState(""); // optional
  const [saving,    setSaving]    = useState(false);
  const [error,     setError]     = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (!firstName.trim() || !lastName.trim() || !phone.trim()) {
      setError("First name, last name, and phone number are required.");
      return;
    }
    setSaving(true);
    try {
      const res = await sbFetch("profiles?id=eq."+userId, {
        method: "PATCH",
        headers: { "Prefer": "return=minimal" },
        body: JSON.stringify({
          first_name: firstName.trim(),
          last_name: lastName.trim(),
          phone: phone.trim(),
          date_of_birth: dob || null,
        }),
      }, accessToken);
      if (!res.ok) throw new Error(await res.text());
      onComplete();
    } catch(err) {
      setError("Could not save your info. Please try again.");
    }
    setSaving(false);
  };

  return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{maxWidth:380, width:"100%", padding:"0 24px"}}>
        <img src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64} alt="BlacktopIQ"
          style={{width:"100%", maxWidth:220, display:"block", margin:"0 auto 24px"}}/>
        <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Welcome to the team!</h1>
        <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
          Let's get your profile set up before you get started.
        </p>
        <form onSubmit={handleSubmit}>
          <div style={S.formGrid}>
            <label style={S.formLabel}>First Name *
              <input type="text" value={firstName} onChange={e => setFirstName(e.target.value)}
                style={S.input} placeholder="First name" required/>
            </label>
            <label style={S.formLabel}>Last Name *
              <input type="text" value={lastName} onChange={e => setLastName(e.target.value)}
                style={S.input} placeholder="Last name" required/>
            </label>
          </div>
          <label style={{...S.formLabel, marginTop:10}}>Phone Number *
            <input type="tel" value={phone} onChange={e => setPhone(e.target.value)}
              style={S.input} placeholder="(555) 555-5555" required/>
          </label>
          <label style={{...S.formLabel, marginTop:10}}>Date of Birth
            <span style={{fontSize:11, color:C.textDim, fontWeight:400}}> (optional)</span>
            <input type="date" value={dob} onChange={e => setDob(e.target.value)}
              style={{...S.input, marginBottom:0}}/>
          </label>
          {error && <div style={{color:C.danger, fontSize:13, marginTop:10}}>{error}</div>}
          <button type="submit" style={{...S.btnPrimary, width:"100%", marginTop:18, opacity:saving?0.6:1}} disabled={saving}>
            {saving ? "Saving..." : "Continue →"}
          </button>
        </form>
      </div>
    </div>
  );
}

// ─── Company Setup Wizard (first login, brand-new tenant's admin) ─────────────
// Shown once, right after a new company is created via the invite flow —
// gated on tenant.data.setupComplete not being true yet. Writes to three
// places: the tenant's own data blob (branding/contact/services), the
// homebase table (geocoded once, same as the dedicated Home Base page would),
// and the rates table — reusing the exact same tables/shape the rest of the
// app already reads from, so nothing downstream needs special-casing a
// "wizard-created" company differently from one set up the long way.
function CompanySetupWizard({ tenant, tFetch, onComplete }) {
  const [companyName, setCompanyName] = useState(tenant?.data?.companyName || "");
  const [phone,        setPhone]        = useState(tenant?.data?.phone || "");
  const [officeEmail,  setOfficeEmail]  = useState(tenant?.data?.officeEmail || "");
  const [address,      setAddress]      = useState("");
  const [logoDataUrl,  setLogoDataUrl]  = useState(tenant?.data?.logoUrl || "");
  const [services,     setServices]     = useState(["sealcoat","crackfill","patch"]);
  const [rates,        setRatesDraft]   = useState(() => {
    const r = {};
    Object.keys(DEFAULT_RATES).forEach(k => { r[k] = DEFAULT_RATES[k].rate; });
    return r;
  });
  const [saving,  setSaving]  = useState(false);
  const [error,   setError]   = useState("");

  const SERVICE_OPTIONS = [
    { key:"sealcoat",  label:"Sealcoat" },
    { key:"crackfill", label:"Crack Fill" },
    { key:"striping",  label:"Line Striping" },
    { key:"patch",     label:"Patching" },
    { key:"other",     label:"Other" },
  ];
  const toggleService = (key) => setServices(prev => prev.includes(key) ? prev.filter(s=>s!==key) : [...prev, key]);

  // Downscale the logo client-side before storing it — an unresized phone
  // photo would bloat the tenant's data blob the same way the original
  // BlacktopIQ asset would have before it was resized server-side.
  const handleLogoFile = (file) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const maxW = 300;
        const scale = Math.min(1, maxW / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        setLogoDataUrl(canvas.toDataURL("image/png"));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (!companyName.trim()) { setError("Company name is required."); return; }
    if (services.length === 0) { setError("Select at least one service you offer."); return; }
    setSaving(true);
    try {
      // 1. Tenant's own branding/contact/services
      const updatedTenantData = {
        ...tenant.data,
        companyName: companyName.trim(),
        phone: phone.trim(),
        officeEmail: officeEmail.trim(),
        logoUrl: logoDataUrl || null,
        servicesOffered: services,
        setupComplete: true,
      };
      const tenantRes = await tFetch("tenants?id=eq." + tenant.tenantId, {
        method: "PATCH",
        body: JSON.stringify({ data: updatedTenantData }),
      });
      if (!tenantRes.ok) throw new Error("Failed to save company info.");

      // 2. Home base — geocode once now, same as the dedicated Home Base page does.
      if (address.trim()) {
        const geo = await geocodeAddress(address.trim());
        await tFetch("homebase?on_conflict=tenant_id", {
          method: "POST",
          headers: { "Prefer": "resolution=merge-duplicates" },
          body: JSON.stringify({ id: 1, data: { address: address.trim(), lat: geo?.lat || null, lng: geo?.lng || null } }),
        });
      }

      // 3. Rates — only for the services they actually offer.
      const ratesData = {};
      services.forEach(key => {
        ratesData[key] = { ...DEFAULT_RATES[key], rate: Number(rates[key]) || 0 };
      });
      await tFetch("rates?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: 1, data: ratesData }),
      });

      onComplete(updatedTenantData);
    } catch(err) {
      setError(err.message || "Something went wrong saving your company setup.");
    }
    setSaving(false);
  };

  return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{maxWidth:480, width:"100%", padding:"24px"}}>
        <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Set Up Your Company</h1>
        <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
          A few things to get {companyName || "your company"} ready to go — you can change any of this later.
        </p>
        <form onSubmit={handleSubmit}>
          <section style={S.section}>
            <h2 style={S.h2}>Branding</h2>
            <label style={S.formLabel}>Company Logo (optional)
              <input type="file" accept="image/*" onChange={e => handleLogoFile(e.target.files?.[0])} style={S.input}/>
            </label>
            {logoDataUrl && (
              <img src={logoDataUrl} alt="Logo preview" style={{maxWidth:160, maxHeight:80, display:"block", marginTop:10, borderRadius:6}}/>
            )}
          </section>

          <section style={S.section}>
            <h2 style={S.h2}>Company Info</h2>
            <label style={S.formLabel}>Company Name
              <input value={companyName} onChange={e => setCompanyName(e.target.value)} style={S.input} required/>
            </label>
            <label style={{...S.formLabel, marginTop:10}}>Phone
              <input type="tel" value={phone} onChange={e => setPhone(e.target.value)} style={S.input}/>
            </label>
            <label style={{...S.formLabel, marginTop:10}}>Office Email
              <input type="email" value={officeEmail} onChange={e => setOfficeEmail(e.target.value)} style={S.input}/>
            </label>
            <label style={{...S.formLabel, marginTop:10}}>Home Base Address
              <input value={address} onChange={e => setAddress(e.target.value)} style={S.input} placeholder="Used for route optimization on the Zones tab"/>
            </label>
          </section>

          <section style={S.section}>
            <h2 style={S.h2}>Services Offered</h2>
            <div style={{display:"flex", flexWrap:"wrap", gap:8}}>
              {SERVICE_OPTIONS.map(s => {
                const selected = services.includes(s.key);
                return (
                  <button key={s.key} type="button" onClick={() => toggleService(s.key)}
                    style={{
                      fontSize:13, fontWeight:600, padding:"8px 14px", borderRadius:20, cursor:"pointer",
                      background: selected ? C.accent : C.surface2,
                      color: selected ? "#000" : C.textMuted,
                      border: `1px solid ${selected ? C.accent : C.border}`,
                    }}>
                    {selected ? "✓ " : ""}{s.label}
                  </button>
                );
              })}
            </div>
          </section>

          {services.length > 0 && (
            <section style={S.section}>
              <h2 style={S.h2}>Starting Rates</h2>
              <p style={{fontSize:11, color:C.textDim, margin:"0 0 10px"}}>Defaults shown — adjust to your own pricing, or leave as-is and change later.</p>
              {services.map(key => (
                <label key={key} style={{...S.formLabel, marginBottom:10}}>
                  {DEFAULT_RATES[key].label} ({DEFAULT_RATES[key].rateLabel})
                  <input type="number" min="0" step="0.01" value={rates[key]}
                    onChange={e => setRatesDraft(prev => ({...prev, [key]: e.target.value}))} style={S.input}/>
                </label>
              ))}
            </section>
          )}

          {error && <div style={{color:C.danger, fontSize:13, marginBottom:12}}>{error}</div>}
          <button type="submit" style={{...S.btnPrimary, width:"100%", opacity:saving?0.6:1}} disabled={saving}>
            {saving ? "Setting up..." : "✓ Finish Setup"}
          </button>
        </form>
      </div>
    </div>
  );
}

function LoginView({ onSuccess }) {
  const [email,    setEmail]    = useState("");
  const [password, setPassword] = useState("");
  const [error,    setError]    = useState("");
  const [loading,  setLoading]  = useState(false);
  const [mode,     setMode]     = useState("login"); // "login" | "forgot"
  const [resetSent, setResetSent] = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();
    setError(""); setLoading(true);
    try {
      const session = await authSignIn(email.trim(), password);
      saveSession(session);
      onSuccess(session);
    } catch(err) {
      setError(err.message || "Login failed. Check your email and password.");
    }
    setLoading(false);
  };

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    setError(""); setLoading(true);
    try {
      await authRequestPasswordReset(email.trim());
      setResetSent(true);
    } catch(err) {
      setError(err.message || "Could not send reset email. Check the address and try again.");
    }
    setLoading(false);
  };

  if (mode === "forgot") {
    return (
      <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
        <div style={{maxWidth:340, width:"100%", padding:"0 24px"}}>
          <img src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64} alt="BlacktopIQ"
            style={{width:"100%", maxWidth:240, display:"block", margin:"0 auto 28px"}}/>
          {resetSent ? (
            <>
              <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Check your email</h1>
              <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
                If an account exists for <strong>{email.trim()}</strong>, a password reset link is on its way. Click it to set a new password.
              </p>
              <button style={{...S.btnSecondary, width:"100%"}}
                onClick={() => { setMode("login"); setResetSent(false); }}>
                ← Back to Sign In
              </button>
            </>
          ) : (
            <>
              <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Reset Password</h1>
              <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
                Enter your email and we'll send you a link to set a new password.
              </p>
              <form onSubmit={handleForgotPassword}>
                <label style={S.formLabel}>Email
                  <input type="email" value={email} onChange={e => setEmail(e.target.value)}
                    style={S.input} autoCapitalize="none" autoCorrect="off" required/>
                </label>
                {error && <div style={{color:C.danger, fontSize:13, marginTop:10}}>{error}</div>}
                <button type="submit" style={{...S.btnPrimary, width:"100%", marginTop:18, opacity:loading?0.6:1}} disabled={loading}>
                  {loading ? "Sending..." : "Send Reset Link"}
                </button>
              </form>
              <button style={{...S.btnSecondary, width:"100%", marginTop:10}}
                onClick={() => { setMode("login"); setError(""); }}>
                ← Back to Sign In
              </button>
            </>
          )}
        </div>
      </div>
    );
  }

  return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{maxWidth:340, width:"100%", padding:"0 24px"}}>
        <img src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64} alt="BlacktopIQ"
          style={{width:"100%", maxWidth:240, display:"block", margin:"0 auto 28px"}}/>
        <form onSubmit={handleLogin}>
          <label style={S.formLabel}>Email
            <input type="email" value={email} onChange={e => setEmail(e.target.value)}
              style={S.input} autoCapitalize="none" autoCorrect="off" required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Password
            <input type="password" value={password} onChange={e => setPassword(e.target.value)}
              style={S.input} required/>
          </label>
          {error && <div style={{color:C.danger, fontSize:13, marginTop:10}}>{error}</div>}
          <button type="submit" style={{...S.btnPrimary, width:"100%", marginTop:18, opacity:loading?0.6:1}} disabled={loading}>
            {loading ? "Signing in..." : "Sign In"}
          </button>
        </form>
        <button
          onClick={() => { setMode("forgot"); setError(""); }}
          style={{background:"none", border:"none", color:C.accent, fontSize:13, cursor:"pointer", display:"block", margin:"14px auto 0", textAlign:"center"}}>
          Forgot password?
        </button>
        <p style={{fontSize:12, color:C.textMuted, textAlign:"center", marginTop:16}}>
          Need an account? Ask your admin to create one for you.
        </p>
      </div>
    </div>
  );
}

export default function App() {
  const [view,          setViewRaw]      = useState("home");
  const [viewHistory,   setViewHistory]  = useState([]); // stack of previous views, for global Back button
  // navigateTo: use this for all "go to a new screen" navigation — pushes the
  // current view onto the history stack so the Back button can return to it.
  const navigateTo = (next) => {
    setViewHistory(h => [...h, view]);
    setViewRaw(next);
  };
  // goBack: pop the last view off the stack and go there directly (no push).
  const goBack = () => {
    setViewHistory(h => {
      if (h.length === 0) return h;
      const prev = h[h.length - 1];
      setViewRaw(prev);
      return h.slice(0, -1);
    });
  };
  const [jobs,          setJobs]         = useState([]);
  const [rates,         setRates]        = useState({...DEFAULT_RATES});
  const [currentJobId,  setCurrentJobId] = useState(null);
  const [loading,       setLoading]      = useState(true);
  const [syncStatus,    setSyncStatus]   = useState("");
  const [laborEntries,  setLaborEntries] = useState([]);
  const [zones,         setZones]        = useState(null);
  const [permissions,   setPermissions]  = useState(null);
  const [homeBase,      setHomeBase]     = useState(null); // { address, lat, lng }
  const [iconStyle,     setIconStyle]    = useState("emoji"); // "emoji" | "lucide" — global, admin-set
  const [teamUsers,     setTeamUsers]    = useState([]);
  const [crews,         setCrews]        = useState([]);
  const [materials,         setMaterials]         = useState([]);
  const [materialSettings,  setMaterialSettings]  = useState(null);
  const [stockChecks,       setStockChecks]       = useState([]);
  const [crmLogs,           setCrmLogs]           = useState([]);
  const [customers,         setCustomers]         = useState([]);
  const isDesktopLayout = useIsDesktop();

  // ── Auth state ──
  const [session,    setSession]    = useState(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [userRole,   setUserRole]   = useState("crew");
  const [userRoles,  setUserRoles]  = useState(["crew"]); // multi-role; userRole stays as the "primary" role for legacy single-role checks
  const [profileNeedsSetup, setProfileNeedsSetup] = useState(false);
  // ── Multi-tenancy: which companies this login belongs to, and which one
  // is currently active. A user can belong to several (tenant_users has one
  // row per membership); we default to the first one found. The actual
  // per-tenant role (set in tenant_users) takes over from the old single
  // profiles.role/roles the moment a tenant is resolved — see fetchTenants.
  const [myTenants,      setMyTenants]      = useState([]); // [{tenantId, role, companyName, data}]
  const [currentTenantId, setCurrentTenantId] = useState(null);

  const [isPlatformAdmin, setIsPlatformAdmin] = useState(false);
  const fetchIsPlatformAdmin = async (accessToken) => {
    try {
      const res = await fetch("/api/check-platform-admin", {
        headers: { "Authorization": "Bearer " + accessToken },
      });
      const data = await res.json();
      setIsPlatformAdmin(!!data?.isPlatformAdmin);
    } catch(e) { setIsPlatformAdmin(false); }
  };

  const fetchTenants = async (userId, accessToken) => {
    try {
      const tuRes = await sbFetch("tenant_users?user_id=eq."+userId+"&status=eq.active&select=tenant_id,role", {}, accessToken);
      const tuData = await tuRes.json();
      if (!Array.isArray(tuData) || tuData.length === 0) { setMyTenants([]); return; }
      const ids = tuData.map(t => t.tenant_id);
      const tRes = await sbFetch("tenants?id=in.("+ids.join(",")+")&select=id,data", {}, accessToken);
      const tData = await tRes.json();
      const merged = tuData.map(tu => {
        const t = (tData||[]).find(x => x.id === tu.tenant_id);
        return { tenantId: tu.tenant_id, role: tu.role, companyName: t?.data?.companyName || "Unknown Company", data: t?.data || {} };
      });
      setMyTenants(merged);
      setCurrentTenantId(prev => {
        // Keep the current pick if it's still valid (e.g. on a profile
        // refresh); otherwise default to the first membership found.
        if (prev && merged.some(m => m.tenantId === prev)) return prev;
        return merged[0]?.tenantId || null;
      });
    } catch(e) { console.error("fetchTenants error:", e); }
  };

  // tFetch: the tenant-aware, auth-aware replacement for sbFetch. Always
  // sends the logged-in user's own access token (not the shared anon key),
  // and for every tenant-scoped table automatically:
  //   - GET:            adds &tenant_id=eq.<current> so reads never see
  //                      another company's rows
  //   - POST/PATCH:      stamps tenant_id onto whatever's being written, so
  //                      new/updated rows always belong to the right company
  //   - DELETE:          adds &tenant_id=eq.<current> too, as a second guard
  //                      against deleting a row that isn't actually yours
  // Tables outside TENANT_SCOPED_TABLES (profiles, tenants, tenant_users,
  // tenant_invites) pass through untouched — those are either global or are
  // how a tenant gets resolved in the first place.
  // NOTE: this scoping is enforced here in application code, NOT yet by RLS
  // (RLS tightening is the deliberately-last step of the multi-tenancy plan,
  // only once everything using tFetch is proven correct).
  const tFetch = (path, opts={}) => {
    const accessToken = session?.access_token;
    const tableName = path.split("?")[0];
    if (!TENANT_SCOPED_TABLES.includes(tableName) || !currentTenantId) {
      return sbFetch(path, opts, accessToken);
    }
    const method = (opts.method || "GET").toUpperCase();
    let finalPath = path;
    let finalOpts = opts;
    if (method === "GET" || method === "DELETE") {
      const sep = path.includes("?") ? "&" : "?";
      finalPath = path + sep + "tenant_id=eq." + currentTenantId;
    } else if (method === "POST" || method === "PATCH") {
      try {
        const bodyObj = JSON.parse(opts.body || "{}");
        if (Array.isArray(bodyObj)) {
          bodyObj.forEach(o => { o.tenant_id = currentTenantId; });
        } else {
          bodyObj.tenant_id = currentTenantId;
        }
        finalOpts = {...opts, body: JSON.stringify(bodyObj)};
      } catch(e) { /* body wasn't JSON — leave it untouched */ }
    }
    return sbFetch(finalPath, finalOpts, accessToken);
  };

  // Switching companies just changes which one tFetch scopes everything to —
  // the main data-load effect re-fires automatically since it depends on
  // currentTenantId. Deliberately NOT touching userRole/userRoles here: that
  // system is global (profiles.roles) and predates per-tenant membership
  // roles (tenant_users.role, which is a single value, not an array) — unifying
  // those is a real decision to make later, not something to collapse
  // silently while just building the switcher.
  const switchTenant = (tenantId) => {
    if (tenantId === currentTenantId) return;
    setCurrentTenantId(tenantId);
  };

  const fetchProfile = async (userId, accessToken) => {
    try {
      const res = await sbFetch("profiles?id=eq."+userId+"&select=role,roles,first_name,last_name,phone", {}, accessToken);
      const data = await res.json();
      if (Array.isArray(data) && data[0]) {
        const profile = data[0];
        if (profile.role) setUserRole(profile.role);
        setUserRoles(Array.isArray(profile.roles) && profile.roles.length ? profile.roles : (profile.role ? [profile.role] : ["crew"]));
        // Admins get their own (future) company setup flow — only gate
        // estimator/crew/crewlead/manager on the basic profile wizard.
        const isAdmin = profile.role === "admin";
        const missingRequired = !profile.first_name?.trim() || !profile.last_name?.trim() || !profile.phone?.trim();
        setProfileNeedsSetup(!isAdmin && missingRequired);
      }
    } catch(e) { console.error("fetchProfile error:", e); }
  };

  // ── Detect Supabase invite/recovery link in the URL hash ──
  const [inviteToken, setInviteToken] = useState(null); // access_token from #...&type=invite|recovery
  // ── Detect a "create a new company" join link — a different mechanism
  // entirely from the above: that one is Supabase inviting an existing-style
  // user by email; this one is a custom token (tenant_invites) for someone
  // who doesn't have an account yet and is about to create a whole new company. ──
  const [joinToken, setJoinToken] = useState(null);

  // ── Restore session on mount ──
  useEffect(() => {
    const joinParam = new URLSearchParams(window.location.search).get("join");
    if (joinParam) {
      setJoinToken(joinParam);
      setAuthChecked(true);
      window.history.replaceState(null, "", window.location.pathname);
      return;
    }

    // Supabase redirects invite/recovery links as:
    // https://yourapp.com/#access_token=...&refresh_token=...&type=invite
    const hash = window.location.hash || "";
    if (hash.includes("access_token") && (hash.includes("type=invite") || hash.includes("type=recovery") || hash.includes("type=signup"))) {
      const params = new URLSearchParams(hash.slice(1));
      const token = params.get("access_token");
      if (token) {
        setInviteToken(token);
        setAuthChecked(true);
        // Clean the sensitive token out of the visible URL once captured
        window.history.replaceState(null, "", window.location.pathname);
        return;
      }
    }

    const restore = async () => {
      const saved = loadSession();
      if (!saved) { setAuthChecked(true); return; }
      const expiresAt = saved.expires_at ? saved.expires_at * 1000 : 0;
      const isExpired = Date.now() > expiresAt - 60000; // refresh if within 1 min of expiry
      if (isExpired && saved.refresh_token) {
        try {
          const fresh = await authRefresh(saved.refresh_token);
          saveSession(fresh);
          setSession(fresh);
          await fetchProfile(fresh.user.id, fresh.access_token);
          await fetchTenants(fresh.user.id, fresh.access_token);
          await fetchIsPlatformAdmin(fresh.access_token);
        } catch(e) {
          clearSession();
        }
      } else {
        setSession(saved);
        await fetchProfile(saved.user.id, saved.access_token);
        await fetchTenants(saved.user.id, saved.access_token);
        await fetchIsPlatformAdmin(saved.access_token);
      }
      setAuthChecked(true);
    };
    restore();
  }, []);

  const handleInvitePasswordSet = async (newSession) => {
    setInviteToken(null);
    saveSession(newSession);
    setSession(newSession);
    await fetchProfile(newSession.user.id, newSession.access_token);
    await fetchTenants(newSession.user.id, newSession.access_token);
    await fetchIsPlatformAdmin(newSession.access_token);
  };

  const handleLoginSuccess = async (newSession) => {
    setSession(newSession);
    await fetchProfile(newSession.user.id, newSession.access_token);
    await fetchTenants(newSession.user.id, newSession.access_token);
    await fetchIsPlatformAdmin(newSession.access_token);
  };

  // After redeem-tenant-invite creates the account + company server-side,
  // this just signs them in for real and clears the join flow.
  const handleJoinSuccess = async (newSession) => {
    setJoinToken(null);
    saveSession(newSession);
    setSession(newSession);
    await fetchProfile(newSession.user.id, newSession.access_token);
    await fetchTenants(newSession.user.id, newSession.access_token);
    await fetchIsPlatformAdmin(newSession.access_token);
  };

  // If the active view isn't allowed for this role, fall back to jobs.
  // "export", "permissions", "team" stay admin-only regardless of the configurable matrix.
  useEffect(() => {
    const alwaysAdminOnly = ["export","permissions","admin","homebase"];
    if (alwaysAdminOnly.includes(view) && userRole !== "admin") { setViewRaw("jobs"); return; }
    if (view === "team" && userRole !== "admin" && userRole !== "manager") { setViewRaw("jobs"); return; }
    if (ALL_TABS.some(t => t.key === view)) {
      const level = getAccessLevel(permissions, view, userRole);
      if (level === "hidden" && userRole !== "admin") setViewRaw("jobs");
    }
  }, [userRole, view, permissions]);

  const handleLogout = () => {
    clearSession();
    setSession(null);
    setUserRole("crew");
    setUserRoles(["crew"]);
    setViewHistory([]);
    setMyTenants([]);
    setCurrentTenantId(null);
    setIsPlatformAdmin(false);
  };

  // ── Load all data — waits for currentTenantId to resolve (so the very
  // first load is correctly scoped, not fired before the tenant is known),
  // and re-fires whenever it changes — i.e. switching companies reloads
  // everything for the newly-selected one. ──
  useEffect(() => {
    if (!currentTenantId) return; // still resolving which company this login belongs to
    setLoading(true);
    const load = async () => {
      try {
        const jr = await tFetch("jobs?select=id,data&order=id.desc");
        const jd = await jr.json();
        if (Array.isArray(jd)) setJobs(jd.map(row => ({...row.data, id: row.id})));

        const rr = await tFetch("rates?select=data&limit=1");
        const rd = await rr.json();
        if (Array.isArray(rd) && rd.length > 0) setRates(rd[0].data);

        const lr = await tFetch("labor?select=id,data&order=id.desc");
        const ld = await lr.json();
        if (Array.isArray(ld)) setLaborEntries(ld.map(row => ({...row.data, id: row.id})));

        const zr = await tFetch("zones?select=data&limit=1");
        const zd = await zr.json();
        if (Array.isArray(zd) && zd.length > 0) setZones(zd[0].data);

        const pr = await tFetch("permissions?select=data&limit=1");
        const pd = await pr.json();
        if (Array.isArray(pd) && pd.length > 0) setPermissions(pd[0].data);

        try {
          const tr = await fetch("/api/list-users?tenantId=" + currentTenantId);
          const td = await tr.json();
          if (tr.ok && Array.isArray(td.users)) setTeamUsers(td.users);
        } catch(e) { console.error("load team users error:", e); }

        const cr = await tFetch("crews?select=id,data&order=id.asc");
        const cd = await cr.json();
        if (Array.isArray(cd)) setCrews(cd.map(row => ({...row.data, id: row.id})));

        const hr = await tFetch("homebase?select=data&limit=1");
        const hd = await hr.json();
        if (Array.isArray(hd) && hd.length > 0) setHomeBase(hd[0].data);

        const sr = await tFetch("appsettings?select=data&limit=1");
        const sd = await sr.json();
        if (Array.isArray(sd) && sd.length > 0 && sd[0].data?.iconStyle) setIconStyle(sd[0].data.iconStyle);

        const mr = await tFetch("materials?select=id,data&order=id.desc");
        const md = await mr.json();
        if (Array.isArray(md)) setMaterials(md.map(row => ({...row.data, id: row.id})));

        const msr = await tFetch("materialsettings?select=data&limit=1");
        const msd = await msr.json();
        if (Array.isArray(msd) && msd.length > 0) setMaterialSettings(msd[0].data);

        const scr = await tFetch("materialstock?select=id,data&order=id.desc");
        const scd = await scr.json();
        if (Array.isArray(scd)) setStockChecks(scd.map(row => ({...row.data, id: row.id})));

        const clr = await tFetch("crmlogs?select=id,data&order=id.desc");
        const cld = await clr.json();
        if (Array.isArray(cld)) setCrmLogs(cld.map(row => ({...row.data, id: row.id})));

        const cur = await tFetch("customers?select=id,data&order=id.desc");
        const cud = await cur.json();
        if (Array.isArray(cud)) setCustomers(cud.map(row => ({...row.data, id: row.id})));
      } catch(e) {
        console.error("Load error:", e);
        setSyncStatus("⚠️ Could not connect to database");
      }
      setLoading(false);
    };
    load();
  }, [currentTenantId]);

  // Jobs commonly get updated from a different login entirely — an admin
  // assigning an estimate, a crew lead marking something completed — and
  // this app has no live/realtime sync between sessions, only a one-time
  // fetch on load. Two complementary fixes for that, short of building full
  // realtime: refetch whenever the tab regains focus (covers "switched away
  // and back"), and poll every 30s while the tab is actually visible (covers
  // two people watching at the same time on separate screens).
  useEffect(() => {
    if (!currentTenantId) return; // don't even attach the listener until a tenant is actually known
    let inFlight = false;
    const refetchJobs = async () => {
      if (inFlight) return;
      inFlight = true;
      try {
        const jr = await tFetch("jobs?select=id,data&order=id.desc");
        const jd = await jr.json();
        if (Array.isArray(jd)) {
          // Don't clobber an edit that hasn't finished syncing yet (the
          // 800ms debounce in updateJob/updateJobById) — keep the local
          // pending version for any job still waiting to write.
          const pending = pendingSyncRef.current || {};
          setJobs(jd.map(row => pending[row.id] || {...row.data, id: row.id}));
        }
      } catch(e) { console.error("Refetch jobs error:", e); }
      inFlight = false;
    };
    const onVisible = () => { if (document.visibilityState === "visible") refetchJobs(); };
    window.addEventListener("focus", refetchJobs);
    document.addEventListener("visibilitychange", onVisible);
    const pollId = setInterval(() => { if (document.visibilityState === "visible") refetchJobs(); }, 30000);
    return () => {
      window.removeEventListener("focus", refetchJobs);
      document.removeEventListener("visibilitychange", onVisible);
      clearInterval(pollId);
    };
  }, [currentTenantId]);

  const syncZones = async (zonesData) => {
    try {
      await tFetch("zones?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: 1, data: zonesData }),
      });
    } catch(e) { console.error("syncZones error:", e); }
  };

  const syncPermissions = async (permissionsData) => {
    try {
      await tFetch("permissions?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: 1, data: permissionsData }),
      });
    } catch(e) { console.error("syncPermissions error:", e); }
  };

  const syncHomeBase = async (homeBaseData) => {
    try {
      await tFetch("homebase?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: 1, data: homeBaseData }),
      });
    } catch(e) { console.error("syncHomeBase error:", e); }
  };

  const syncIconStyle = async (style) => {
    setIconStyle(style);
    try {
      await tFetch("appsettings?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: 1, data: { iconStyle: style } }),
      });
    } catch(e) { console.error("syncIconStyle error:", e); }
  };

  // Assign a newly created/edited job to its nearest existing zone centroid
  // (lightweight live update — does not recalculate centroids themselves)
  const assignJobToNearestZone = async (job) => {
    if (!zones?.list?.length) return;

    // If this job's status isn't one of the categories the zones were built for,
    // make sure it isn't sitting in a zone/overflow list, and stop — no geocoding needed.
    if (zones.filterStatuses && !zones.filterStatuses.includes(job.status)) {
      const stillPresent = zones.list.some(z => z.jobIds.includes(job.id)) || (zones.overflow?.jobIds||[]).includes(job.id);
      if (!stillPresent) return;
      const cleared = {...zones};
      cleared.list = zones.list.map(z => ({
        ...z,
        jobIds: z.jobIds.filter(id => id !== job.id),
        jobCount: z.jobIds.filter(id => id !== job.id).length,
      }));
      cleared.overflow = {...cleared.overflow, jobIds: (cleared.overflow?.jobIds||[]).filter(id => id !== job.id)};
      cleared.overflow.count = cleared.overflow.jobIds.length;
      setZones(cleared);
      syncZones(cleared);
      return;
    }

    // Already geocoded — reuse it. Trust legacy records with no geoAddr yet;
    // only force a re-geocode when geoAddr is present and no longer matches,
    // or the cached coordinates are implausibly far from home base.
    const addrStr = fullAddressOf(job);
    if (!addrStr) return;
    // A bare state alone isn't specific enough to geocode reliably — skip rather
    // than risk plotting the job in the wrong country (e.g. "PA" → Panama).
    if (!hasSufficientAddress(job)) return;
    const cached = job.geoLat && job.geoLng && (!job.geoAddr || job.geoAddr === addrStr)
      && !isImplausibleLocation({lat: job.geoLat, lng: job.geoLng}, homeBase);
    const geo = cached ? { lat: job.geoLat, lng: job.geoLng } : await geocodeAddress(geocodeQueryOf(job), homeBase);
    if (!geo) return;
    if (!cached) {
      try {
        await tFetch("jobs?id=eq."+job.id, {
          method: "PATCH",
          body: JSON.stringify({ data: {...job, geoLat: geo.lat, geoLng: geo.lng, geoAddr: addrStr} }),
        });
      } catch(e) {}
      setJobs(prev => prev.map(jj => jj.id === job.id ? {...jj, geoLat: geo.lat, geoLng: geo.lng, geoAddr: addrStr} : jj));
    }

    let bestIdx = -1, bestDist = Infinity;
    zones.list.forEach((z, i) => {
      const d = haversine(geo, z.centroid);
      if (d < bestDist) { bestDist = d; bestIdx = i; }
    });

    const updatedZones = {...zones};
    const isOverflow = bestDist > 25;
    updatedZones.list = zones.list.map((z, i) => ({
      ...z,
      jobIds: z.jobIds.filter(id => id !== job.id).concat(i===bestIdx && !isOverflow ? [job.id] : []),
      jobCount: z.jobIds.filter(id => id !== job.id).concat(i===bestIdx && !isOverflow ? [job.id] : []).length,
    }));
    updatedZones.overflow = {
      ...updatedZones.overflow,
      jobIds: (updatedZones.overflow?.jobIds||[]).filter(id => id !== job.id).concat(isOverflow ? [job.id] : []),
    };
    updatedZones.overflow.count = updatedZones.overflow.jobIds.length;

    setZones(updatedZones);
    syncZones(updatedZones);
  };

  const syncLaborEntry = async (entry) => {
    try {
      await tFetch("labor", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncLaborEntry error:", e); }
  };

  const deleteLaborEntry = async (id) => {
    setLaborEntries(prev => prev.filter(e => e.id !== id));
    try { await tFetch("labor?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  const addLaborEntry = (entry) => {
    setLaborEntries(prev => [entry, ...prev]);
    syncLaborEntry(entry);
  };

  // ── Material purchases (Materials tab) ──
  const syncMaterial = async (entry) => {
    try {
      await tFetch("materials", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncMaterial error:", e); }
  };

  const addMaterial = (entry) => {
    setMaterials(prev => [entry, ...prev]);
    syncMaterial(entry);
  };

  const deleteMaterial = async (id) => {
    setMaterials(prev => prev.filter(m => m.id !== id));
    try { await tFetch("materials?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  const syncMaterialSettings = async (settingsData) => {
    try {
      await tFetch("materialsettings?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: 1, data: settingsData }),
      });
    } catch(e) { console.error("syncMaterialSettings error:", e); }
  };

  // ── Material stock checks (physical on-hand readings) ──
  const syncStockCheck = async (entry) => {
    try {
      await tFetch("materialstock", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncStockCheck error:", e); }
  };

  const addStockCheck = (entry) => {
    setStockChecks(prev => [entry, ...prev]);
    syncStockCheck(entry);
  };

  const deleteStockCheck = async (id) => {
    setStockChecks(prev => prev.filter(c => c.id !== id));
    try { await tFetch("materialstock?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  // ── CRM notes / call logs ──
  const syncCrmLog = async (entry) => {
    try {
      await tFetch("crmlogs", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncCrmLog error:", e); }
  };

  const addCrmLog = (entry) => {
    setCrmLogs(prev => [entry, ...prev]);
    syncCrmLog(entry);
  };

  const deleteCrmLog = async (id) => {
    setCrmLogs(prev => prev.filter(l => l.id !== id));
    try { await tFetch("crmlogs?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  // ── Customers (CRM) ──
  const syncCustomer = async (entry) => {
    try {
      await tFetch("customers", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncCustomer error:", e); }
  };

  const addCustomer = (entry) => {
    setCustomers(prev => [entry, ...prev]);
    syncCustomer(entry);
  };

  const updateCustomer = (id, fields) => {
    setCustomers(prev => prev.map(c => {
      if (c.id !== id) return c;
      const updated = {...c, ...fields};
      syncCustomer(updated);
      return updated;
    }));
  };

  // ── Upsert a single job ──
  const lastZonedAddressRef = useRef({});

  const syncJob = async (job) => {
    setSyncStatus("Saving...");
    try {
      const res = await tFetch("jobs", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: job.id, data: job }),
      });
      if (!res.ok) throw new Error(await res.text());
      setSyncStatus("✓ Saved");
      setTimeout(() => setSyncStatus(""), 2000);

      // Live zone re-assignment — only re-geocode/re-assign if the address actually changed
      const addrStr = fullAddressOf(job);
      if (addrStr && zones?.list?.length && lastZonedAddressRef.current[job.id] !== addrStr) {
        lastZonedAddressRef.current[job.id] = addrStr;
        assignJobToNearestZone(job);
      }
    } catch(e) {
      console.error("syncJob error:", e);
      setSyncStatus("⚠️ Save failed");
    }
  };

  // ── Upsert rates ──
  const syncRates = async (r) => {
    setSyncStatus("Saving...");
    try {
      const res = await tFetch("rates?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: 1, data: r }),
      });
      if (!res.ok) throw new Error(await res.text());
      setSyncStatus("✓ Saved");
      setTimeout(() => setSyncStatus(""), 2000);
    } catch(e) {
      console.error("syncRates error:", e);
      setSyncStatus("⚠️ Save failed");
    }
  };

  // ── Delete a job ──
  const deleteJob = async (id) => {
    setJobs(prev => prev.filter(j => j.id !== id));
    try {
      await tFetch("jobs?id=eq." + id, { method: "DELETE" });
    } catch(e) { console.error("deleteJob error:", e); }
  };

  const currentJob = jobs.find(j => j.id === currentJobId) || null;

  // Keep a ref of pending syncs so debounce always uses latest state
  const pendingSyncRef = useRef({});
  const syncTimerRef   = useRef({});

  // Stamps statusChangedAt whenever fn() actually changes a job's status —
  // this is the only place that needs to know, since every status change in
  // the app (drag-and-drop, dropdowns, workflow buttons) goes through one of
  // these two functions. Powers the aging report: without this, there'd be
  // no way to know how long a job has actually been sitting at its current
  // stage, only when it was originally created.
  const withStatusStamp = (job, fn) => {
    const result = fn(job);
    if (result.status !== job.status) result.statusChangedAt = new Date().toISOString();
    return result;
  };

  const updateJob = fn => {
    setJobs(prev => {
      const next = prev.map(j => {
        if (j.id !== currentJobId) return j;
        return withStatusStamp(j, fn);
      });
      // Find updated job and schedule debounced sync
      const updated = next.find(j => j.id === currentJobId);
      if (updated) {
        pendingSyncRef.current[updated.id] = updated;
        clearTimeout(syncTimerRef.current[updated.id]);
        syncTimerRef.current[updated.id] = setTimeout(() => {
          const toSync = pendingSyncRef.current[updated.id];
          if (toSync) syncJob(toSync);
          delete pendingSyncRef.current[updated.id];
        }, 800);
      }
      return next;
    });
  };

  // Update any job by ID (used for scheduling, status changes, etc.)
  const updateJobById = (id, fn) => {
    setJobs(prev => {
      const next = prev.map(j => j.id===id ? withStatusStamp(j, fn) : j);
      const updated = next.find(j => j.id===id);
      if (updated) {
        pendingSyncRef.current[updated.id] = updated;
        clearTimeout(syncTimerRef.current[updated.id]);
        syncTimerRef.current[updated.id] = setTimeout(() => {
          const toSync = pendingSyncRef.current[updated.id];
          if (toSync) syncJob(toSync);
          delete pendingSyncRef.current[updated.id];
        }, 800);
      }
      return next;
    });
  };

  const setCurrentJob = job => setCurrentJobId(job ? job.id : null);

  const handleSetRates = (r) => { setRates(r); syncRates(r); };

  const handleSetJobs = (fnOrArr) => {
    // Used by the Jobs pipeline for create/delete
    setJobs(prev => {
      const next = typeof fnOrArr === "function" ? fnOrArr(prev) : fnOrArr;
      // Detect new job (added to front)
      if (next.length > prev.length) {
        const newJob = next[0];
        tFetch("jobs", {
          method: "POST",
          headers: { "Prefer": "resolution=merge-duplicates" },
          body: JSON.stringify({ id: newJob.id, data: newJob }),
        });
      }
      return next;
    });
  };

  if (!authChecked) return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{textAlign:"center", padding:"0 40px"}}>
        <img
          src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64}
          alt="BlacktopIQ"
          style={{width:"100%", maxWidth: isDesktopLayout ? 560 : 420, display:"block", margin:"0 auto"}}
        />
      </div>
    </div>
  );

  if (inviteToken) return <SetPasswordView inviteToken={inviteToken} onSuccess={handleInvitePasswordSet}/>;
  if (joinToken) return <JoinCompanyView token={joinToken} onSuccess={handleJoinSuccess}/>;

  if (!session) return <LoginView onSuccess={handleLoginSuccess}/>;

  if (profileNeedsSetup) return (
    <ProfileSetupWizard
      accessToken={session.access_token}
      userId={session.user?.id}
      onComplete={() => setProfileNeedsSetup(false)}
    />
  );

  // Only a brand-new tenant (created via the join flow, which explicitly
  // sets setupComplete:false) triggers this — an absent field (e.g. TPS's
  // own pre-existing tenant row, migrated without this field at all) does
  // NOT trigger it. That distinction matters: falsy-but-absent should mean
  // "this predates the wizard, leave it alone," not "show the wizard."
  const currentTenant = myTenants.find(t => t.tenantId === currentTenantId);
  if (userRole === "admin" && currentTenant && currentTenant.data?.setupComplete === false) {
    return (
      <CompanySetupWizard
        tenant={currentTenant}
        tFetch={tFetch}
        onComplete={(updatedData) => {
          setMyTenants(prev => prev.map(t => t.tenantId===currentTenantId ? {...t, data: updatedData, companyName: updatedData.companyName} : t));
        }}
      />
    );
  }

  if (loading) return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{textAlign:"center", padding:"0 40px"}}>
        <img
          src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64}
          alt="BlacktopIQ"
          style={{width:"100%", maxWidth: isDesktopLayout ? 560 : 420, display:"block", margin:"0 auto"}}
        />
        <div style={{color:C.textMuted, fontSize:13, marginTop:20, letterSpacing:"0.08em"}}>Loading...</div>
      </div>
    </div>
  );

  return (
    <div style={isDesktopLayout ? S.appDesktop : S.app}>
      <TopNav view={view} setView={navigateTo} userRole={userRole} userRoles={userRoles} permissions={permissions} onLogout={handleLogout} iconStyle={iconStyle} myTenants={myTenants} currentTenantId={currentTenantId} switchTenant={switchTenant}/>
      <div style={isDesktopLayout ? S.contentColDesktop : undefined}>
        {syncStatus && (
          <div style={{
            background: syncStatus.startsWith("⚠️") ? "#fee2e2" : "#dcfce7",
            color: syncStatus.startsWith("⚠️") ? C.danger : C.green,
            fontSize:11, textAlign:"center", padding:"3px 0",
          }}>{syncStatus}</div>
        )}
        <div style={S.content}>
        {viewHistory.length > 0 && (
          <div style={{display:"flex", justifyContent:"flex-end", padding:"16px 24px 0", boxSizing:"border-box"}}>
            <button onClick={goBack} style={S.btnSecondary}>← Back</button>
          </div>
        )}
        {getAccessLevel(permissions,"home",userRoles)!=="hidden" && <div style={{display: view==="home" ? "block" : "none"}}><HomeView jobs={jobs} crews={crews} userRole={userRole} userRoles={userRoles} userId={session?.user?.id} setCurrentJob={setCurrentJob} setView={navigateTo}/></div>}
        {getAccessLevel(permissions,"jobs",userRoles)!=="hidden" && <div style={{display: view==="jobs" ? "block" : "none"}}><JobsPipelineView jobs={jobs} setJobs={handleSetJobs} setCurrentJob={setCurrentJob} setView={navigateTo} rates={rates} updateJobById={updateJobById} userRole={userRole} userRoles={userRoles} userId={session?.user?.id}/></div>}
        {getAccessLevel(permissions,"jobs",userRoles)!=="hidden" && <div style={{display: view==="myjobs" ? "block" : "none"}}><JobsPipelineView jobs={jobs} setJobs={handleSetJobs} setCurrentJob={setCurrentJob} setView={navigateTo} rates={rates} updateJobById={updateJobById} userRole={userRole} userRoles={userRoles} userId={session?.user?.id} scope="mine" showBackButton/></div>}
        {getAccessLevel(permissions,"schedule",userRoles)!=="hidden" && <div style={{display: view==="schedule" ? "block" : "none"}}><ScheduleView jobs={jobs} setCurrentJob={setCurrentJob} setView={navigateTo}/></div>}
        {getAccessLevel(permissions,"zones",userRoles)!=="hidden" && <div style={{display: view==="zones" ? "block" : "none"}}><ZonesView jobs={jobs} setJobs={setJobs} zones={zones} setZones={setZones} syncZones={syncZones} setCurrentJob={setCurrentJob} setView={navigateTo} homeBase={homeBase} tFetch={tFetch}/></div>}
        {view==="jobdetail" && <JobDetailView currentJob={currentJob} updateJob={updateJob} deleteJob={deleteJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}} setView={navigateTo} teamUsers={teamUsers} crews={crews} zones={zones} homeBase={homeBase} userRole={userRole} userRoles={userRoles} userId={session?.user?.id} jobs={jobs}/>}
        {view==="estimate" && getAccessLevel(permissions,"estimate",userRoles)!=="hidden" && <EstimateView currentJob={currentJob} updateJob={updateJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}} syncJob={syncJob}
          canOverridePrice={hasRole(userRoles||[userRole], "admin") || hasRole(userRoles||[userRole], "manager")}
          readOnly={
          getAccessLevel(permissions,"estimate",userRoles)==="view" ||
          // An estimator-only viewer (no admin/manager) can't touch measurements
          // once it's submitted for review or has moved past Estimate/Draft —
          // editing after the fact would invalidate whatever the manager/admin
          // already reviewed, sent, or the client already signed off on.
          (hasRole(userRoles||[userRole], "estimator") && !(hasRole(userRoles||[userRole], "admin") || hasRole(userRoles||[userRole], "manager")) &&
            (currentJob?.readyForReview || !["estimate","draft"].includes(currentJob?.status)))
        }/>}
        {view==="costs"    && getAccessLevel(permissions,"costs",userRoles)!=="hidden" && <CostsView   currentJob={currentJob} updateJob={updateJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}}/>}
        {view==="invoice"  && getAccessLevel(permissions,"invoice",userRoles)!=="hidden" && <InvoiceView  currentJob={currentJob} updateJob={updateJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}}/>}
        {getAccessLevel(permissions,"labor",userRoles)!=="hidden" && <div style={{display: view==="labor" ? "block" : "none"}}><LaborView   laborEntries={laborEntries} addLaborEntry={addLaborEntry} deleteLaborEntry={deleteLaborEntry} userRole={userRole} teamUsers={teamUsers} currentUserId={session?.user?.id}/></div>}
        {getAccessLevel(permissions,"materials",userRoles)!=="hidden" && <div style={{display: view==="materials" ? "block" : "none"}}><MaterialsView jobs={jobs} materials={materials} addMaterial={addMaterial} deleteMaterial={deleteMaterial} materialSettings={materialSettings} setMaterialSettings={setMaterialSettings} syncMaterialSettings={syncMaterialSettings} stockChecks={stockChecks} addStockCheck={addStockCheck} deleteStockCheck={deleteStockCheck} userRole={userRole}/></div>}
        {getAccessLevel(permissions,"crm",userRoles)!=="hidden" && <div style={{display: view==="crm" ? "block" : "none"}}><CRMView jobs={jobs} rates={rates} customers={customers} addCustomer={addCustomer} updateCustomer={updateCustomer} updateJobById={updateJobById} crmLogs={crmLogs} addCrmLog={addCrmLog} deleteCrmLog={deleteCrmLog} setCurrentJob={setCurrentJob} setView={navigateTo} userRole={userRole}/></div>}
        {getAccessLevel(permissions,"reports",userRoles)!=="hidden" && <div style={{display: view==="reports" ? "block" : "none"}}><ReportsView  jobs={jobs} rates={rates} setCurrentJob={setCurrentJob} setView={navigateTo}/></div>}
        {view==="rates"    && getAccessLevel(permissions,"rates",userRoles)!=="hidden" && <RatesView   rates={rates} setRates={handleSetRates} currentJob={currentJob} updateJob={updateJob} setCurrentJob={setCurrentJob}/>}
        {view==="homebase" && userRole==="admin" && <HomeBaseView homeBase={homeBase} setHomeBase={setHomeBase} syncHomeBase={syncHomeBase} setView={navigateTo}/>}
        {view==="team"     && (userRole==="admin"||userRole==="manager") && <TeamView accessToken={session?.access_token} userRole={userRole} tFetch={tFetch} tenantId={currentTenantId}/>}
        {view==="admin"    && userRole==="admin" && <AdminHubView setView={navigateTo} setCurrentJob={setCurrentJob} iconStyle={iconStyle} syncIconStyle={syncIconStyle} accessToken={session?.access_token} isPlatformAdmin={isPlatformAdmin}/>}
        {view==="permissions" && userRole==="admin" && <PermissionsView permissions={permissions} setPermissions={setPermissions} syncPermissions={syncPermissions} setView={navigateTo}/>}
        {view==="account" && <UserSettingsView accessToken={session?.access_token} userId={session?.user?.id} setView={navigateTo} onLogout={handleLogout}/>}
        {view==="export"   && userRole==="admin" && <ExportView  jobs={jobs} laborEntries={laborEntries} rates={rates} setView={navigateTo}/>}
        </div>
      </div>
    </div>
  );
}
